export class ManageUsersComponent {
  adminService = inject(AdminService);
  cdr = inject(ChangeDetectorRef);
  assetsUrl = environment.assetsUrl;
  usersList = [];
  isLoading = false;
  searchTerm = '';
  selectedUser = null;
  showUserCard = false;
  isUserEditMode = false;
  userEditData = {};
  get filteredUsers() {
    if (!this.searchTerm || !this.searchTerm.trim()) {
      return this.usersList;
    }
    const q = this.searchTerm.toLowerCase();
    return this.usersList.filter(user => (user.name || '').toLowerCase().includes(q) || (user.email || '').toLowerCase().includes(q) || (user.role || '').toLowerCase().includes(q));
  }
  ngOnInit() {
    this.isLoading = true;
    this.adminService.getAllUsers().subscribe({
      next: data => {
        this.usersList = data;
        this.isLoading = false;
        this.cdr.detectChanges();
      },
      error: () => this.isLoading = false
    });
  }
  // ... votre code actuel et votre fonction onDeleteUser ...
  onDeleteUser(userId) {
    if (confirm("⚠️ Êtes-vous sûr de vouloir supprimer définitivement cet utilisateur de Tun-Job ?")) {
      this.adminService.deleteUser(userId).subscribe({
        next: () => {
          this.usersList = this.usersList.filter(u => u.id !== userId);
          this.cdr.detectChanges();
        }
      });
    }
  }
  openUserCard(user) {
    this.selectedUser = {
